I'll build a complete Node.js/Express implementation. Paste this into separate files or adapt to your stack.

**package.json** (dependencies):
```json
{
  "dependencies": {
    "express": "^4.18.0",
    "bcrypt": "^5.1.0",
    "jsonwebtoken": "^9.0.0"
  }
}
```

**auth.js** (core implementation):
```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

const SECRET = process.env.JWT_SECRET || 'dev-secret-change-in-production';
const users = new Map(); // Replace with DB in production
const failedAttempts = new Map(); // Track by email:ip

const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 min
const MAX_FAILED_ATTEMPTS = 5;

function getAttemptKey(email, ip) {
  return `${email}:${ip}`;
}

function checkRateLimit(key) {
  const record = failedAttempts.get(key);
  if (!record) return { allowed: true };

  const now = Date.now();
  if (now - record.firstAttempt > RATE_LIMIT_WINDOW) {
    failedAttempts.delete(key);
    return { allowed: true };
  }

  if (record.count >= MAX_FAILED_ATTEMPTS) {
    const secondsLeft = Math.ceil((RATE_LIMIT_WINDOW - (now - record.firstAttempt)) / 1000);
    return { allowed: false, retryAfter: secondsLeft };
  }

  return { allowed: true };
}

function recordFailure(key) {
  const record = failedAttempts.get(key) || { count: 0, firstAttempt: Date.now() };
  record.count++;
  failedAttempts.set(key, record);
}

function clearFailures(key) {
  failedAttempts.delete(key);
}

// Signup
app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  if (users.has(email)) {
    return res.status(409).json({ error: 'User already exists' });
  }

  try {
    const hashedPassword = await bcrypt.hash(password, 10);
    users.set(email, hashedPassword);
    res.status(201).json({ message: 'Signup successful' });
  } catch (err) {
    res.status(500).json({ error: 'Signup failed' });
  }
});

// Login
app.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const clientIp = req.ip;
  const key = getAttemptKey(email, clientIp);

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  const rateLimit = checkRateLimit(key);
  if (!rateLimit.allowed) {
    return res.status(429).json({
      error: `Too many failed attempts. Try again in ${rateLimit.retryAfter} seconds.`
    });
  }

  const hashedPassword = users.get(email);
  if (!hashedPassword) {
    recordFailure(key);
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  try {
    const match = await bcrypt.compare(password, hashedPassword);
    if (!match) {
      recordFailure(key);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    clearFailures(key);
    const token = jwt.sign({ email }, SECRET, { expiresIn: '24h' });
    res.json({ token });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

// Verify token middleware
function verifyToken(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid token' });
  }

  const token = auth.slice(7);
  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Protected route example
app.get('/me', verifyToken, (req, res) => {
  res.json({ email: req.user.email });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server on port ${PORT}`));
```

**Usage:**
```bash
npm install
node auth.js
```

Test it:
```bash
# Signup
curl -X POST http://localhost:3000/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}'

# Login
curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}'
# Returns: {"token":"..."}

# Protected route
curl -X GET http://localhost:3000/me \
  -H "Authorization: Bearer YOUR_TOKEN"
```

**Chisle notes:** In-memory storage for demo; swap `Map` with DB queries. Rate limit tracker persists in memory; switch to Redis for multi-server. JWT is stateless (good for scaling); use session store if you need server-side revocation. Password rules (8 char min, etc.) adjust to your policy.
